    can_fix = has_phone and not phone_valid and text.length(national) == 10
    phone_arg = ("+1" + national) if can_fix else null
    has_email = contact.email != null and "@" in contact.email
    domain = text.lower(text.split(contact.email, "@")[1]) if has_email else ""
    company_empty = contact.company == null or contact.company == ""
    needs_company = company_empty and has_email and domain in domain_map
    company_arg = domain_map[domain] if needs_company else null
    should_update = can_fix or needs_company
    updated = if should_update {
        u = boundary retry 2 {
            return update_contact({ id: contact.id, phone: phone_arg, company: company_arg })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
        return u
    } else {
        return null
    }
    return { pf: can_fix, cf: needs_company }
}
phones_fixed = fold acc = 0 for r in results { return acc + (1 if r.pf else 0) }
companies_filled = fold acc = 0 for r in results { return acc + (1 if r.cf else 0) }
submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submitted }
